    static const char *M[] = { "objfpc", "delphi", "tp", "fpc", "macpas" };
    static const int D[] = { PAS_DIALECT_OBJFPC, PAS_DIALECT_DELPHI, PAS_DIALECT_FPC, PAS_DIALECT_FPC, PAS_DIALECT_FPC };
